class Solution {
  public int longestArithmetic(int[] nums) {
    int n = nums.length;
    int[] left = new int[n], right = new int[n];
    for (int i = 0; i < n; i++) {
      if (i >= 2 && nums[i] - nums[i - 1] == nums[i - 1] - nums[i - 2]) left[i] = left[i - 1] + 1;
      else left[i] = i >= 1 ? 2 : 1;
    }
    for (int i = n - 1; i >= 0; i--) {
      if (i + 2 < n && nums[i + 1] - nums[i] == nums[i + 2] - nums[i + 1])
        right[i] = right[i + 1] + 1;
      else right[i] = i + 1 < n ? 2 : 1;
    }
    int best = 1;
    for (int i = 0; i < n; i++) best = Math.max(best, left[i]);
    for (int i = 0; i < n; i++) {
      if (i >= 1) best = Math.max(best, left[i - 1] + 1);
      if (i + 1 < n) best = Math.max(best, right[i + 1] + 1);
      if (i >= 1 && i + 1 < n) {
        int span = nums[i + 1] - nums[i - 1];
        if (span % 2 != 0) continue;
        int d = span / 2;
        int lenLeft = left[i - 1] >= 2 && nums[i - 1] - nums[i - 2] == d ? left[i - 1] : 1;
        int lenRight = right[i + 1] >= 2 && nums[i + 2] - nums[i + 1] == d ? right[i + 1] : 1;
        best = Math.max(best, lenLeft + lenRight + 1);
      }
    }
    return best;
  }
}
